def docker_lint(text: str) -> list[str]:
    lines = [l.strip() for l in text.splitlines() if l.strip()]
    p = []
    for l in lines:
        if l.upper().startswith('FROM '):
            img = l.split()[1]
            if ':' not in img or img.endswith(':latest'):
                p.append('pin base image')
                break
    if not any(l.upper().startswith('USER ') for l in lines):
        p.append('runs as root')
    copy_all = next((i for i, l in enumerate(lines) if l == 'COPY . .'), None)
    deps = next((i for i, l in enumerate(lines) if l.startswith('COPY') and 'pyproject.toml' in l), None)
    if copy_all is not None and (deps is None or copy_all < deps):
        p.append('copy deps first')
    return p

